def cable_losses(n, cables):
    losses = []
    for cut in range(len(cables)):
        start = cables[cut][0]
        goal = cables[cut][1]
        counts = []
        separated = False
        for station in [start, goal]:
            seen = {station: True}
            stack = [station]
            while len(stack) > 0:
                here = stack.pop()
                for i in range(len(cables)):
                    if i == cut:
                        continue
                    line = cables[i]
                    other = -1
                    if line[0] == here:
                        other = line[1]
                    elif line[1] == here:
                        other = line[0]
                    if other >= 0 and other not in seen:
                        seen[other] = True
                        stack.append(other)
            counts.append(len(seen))
            if station == start and goal not in seen:
                separated = True
        loss = 0
        if separated:
            loss = counts[0] * counts[1]
        losses.append(loss)
    return losses

